package com.phoenix.business.web; import com.phoenix.business.domain.*;import com.phoenix.business.repository.*;import com.phoenix.business.service.AuditService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/payments") @RequiredArgsConstructor public class PaymentController {private final PaymentService service;private final PaymentRepository repo;private final com.phoenix.business.service.ReceiptService receipts;record Renewal(@NotNull Long memberId,@NotNull Long planId,@NotNull Payment.Method method,String referenceNote,BigDecimal amount){}@PostMapping("/renew")public Payment renew(@Valid @RequestBody Renewal q,Authentication a){return service.renew(q,a.getName());}@GetMapping public Page<Payment> list(@RequestParam(required=false)LocalDate from,@RequestParam(required=false)LocalDate to,@PageableDefault(size=20,sort="paymentDate",direction=Sort.Direction.DESC)Pageable p){ZoneId z=ZoneOffset.UTC;Instant a=(from==null?LocalDate.of(2000,1,1):from).atStartOfDay(z).toInstant();Instant b=(to==null?LocalDate.now().plusDays(1):to.plusDays(1)).atStartOfDay(z).toInstant();return repo.findByPaymentDateBetween(a,b,p);}@GetMapping(value="/{id}/receipt.pdf",produces="application/pdf")public org.springframework.http.ResponseEntity<byte[]> receipt(@PathVariable Long id)throws Exception{return org.springframework.http.ResponseEntity.ok().header("Content-Disposition","attachment; filename=receipt.pdf").body(receipts.create(id));}}
@Service @RequiredArgsConstructor class PaymentService {private final PaymentRepository payments;private final MemberRepository members;private final MembershipPlanRepository plans;private final UserRepository users;private final AuditService audit;@Transactional Payment renew(PaymentController.Renewal q,String username){Member m=members.findById(q.memberId()).orElseThrow();MembershipPlan plan=plans.findById(q.planId()).filter(MembershipPlan::isActive).orElseThrow();User user=users.findByUsernameIgnoreCase(username).orElseThrow();LocalDate today=LocalDate.now(),start=m.getExpiryDate()!=null&&m.getExpiryDate().isAfter(today)?m.getExpiryDate().plusDays(1):today,end=start.plusMonths(plan.getDurationMonths()).minusDays(1);Payment p=new Payment();p.setReceiptNumber("PHX-"+LocalDate.now().getYear()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());p.setMember(m);p.setPlan(plan);p.setPlanNameSnapshot(plan.getName());p.setPeriodStart(start);p.setPeriodEnd(end);p.setPaymentDate(Instant.now());p.setAmount(q.amount()==null?plan.getPrice():q.amount());p.setMethod(q.method());p.setReferenceNote(q.referenceNote());p.setReceivedBy(user);p=payments.save(p);m.setPlan(plan);m.setMembershipStartDate(start);m.setExpiryDate(end);m.setStatus(Member.Status.ACTIVE);members.save(m);audit.record("MEMBERSHIP_RENEWED","MEMBER",m.getId(),"Receipt "+p.getReceiptNumber()+", plan "+plan.getName());audit.record("PAYMENT_CREATED","PAYMENT",p.getId(),"Receipt "+p.getReceiptNumber());return p;}}
